import{z as i,x as s,o as l,c as F,q as A,j as n,D as e,d as t,s as r,S as B,b as E}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"拒绝采样数据循环","description":"","frontmatter":{"title":"拒绝采样数据循环","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rft-data-loop.md","filePath":"llm/rft-data-loop.md","lastUpdated":1791413859000}'),p={name:"llm/rft-data-loop.md"};function T(d,a,m,h,R,f){const o=s("Mermaid");return l(),F("div",null,[a[2]||(a[2]=A('<h1 id="拒绝采样数据循环" tabindex="-1">拒绝采样数据循环 <a class="header-anchor" href="#拒绝采样数据循环" aria-label="Permalink to &quot;拒绝采样数据循环&quot;">​</a></h1><div class="epigraph"><p>用当前策略生成许多完成，留下奖励或验证器通过的那些，再当示范做 SFT；探索发生在采样里，学习仍然是监督学习。</p><footer>—— Yuan 等数学上的 Rejection Sampling Fine-Tuning（2023）；Dong 等 RAFT（TMLR 2023）；Llama 2-Chat 亦用拒绝采样</footer></div><p><a href="/llm/sft-vs-rl-efficiency">上一课</a>把缺口分成格式、排序与搜索。拒绝采样微调（RFT / RAFT）是搜索缺口上的中间道路：不训练在线 PPO，也不满足于静态示范。循环是：采样 → 打分 → 过滤 → SFT → 更新策略再采样。Yuan 等人在数学推理上展示「生成–筛选–再训」随采样数扩展；Dong 等人的 RAFT 用奖励模型给完成打分再微调；Touvron 等人在 Llama 2-Chat 里同样使用拒绝采样阶段。本课写这个数据闭环，并结束「SFT 工程」单元。下一单元从 <a href="/llm/rslora">rsLoRA</a> 回到参数高效。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态 SFT 的 \\(y\\) 来自人或教师，与学生当前 \\(p_\\theta(\\cdot\\mid x)\\) 可能离得很远：学生学的是模仿离线轨迹，推理时却从自己的分布采样，训练–解码错位。在线 RL 对齐分布，但要维护奖励模型、KL、价值头。拒绝采样只保留学生<strong>已经能生成</strong>且分数高的 \\(y\\)，再对这些 \\(y\\) 做<a href="/llm/response-only-loss">仅回复 SFT</a>，分布天然 on-policy 或近 on-policy。</p><p><span class="marginnote">术语翻译：拒绝采样就是「多写几份、只交最好的那份」。对一道题让模型自己采 \\(N\\) 个答案，用判分器把不及格的扔掉，及格的拿来当示范再教它——探索靠多采样，学习仍是最普通的监督学习。</span></p><p>问题变成工程循环：每轮采多少、阈值怎么定、失败样本是否当负例、循环几次后奖励黑客出现。没有循环就退化成一次性 Best-of-N 蒸馏；循环过多又在刷奖励模型癖好。</p><h3 id="过滤器就是奖励" tabindex="-1">过滤器就是奖励 <a class="header-anchor" href="#过滤器就是奖励" aria-label="Permalink to &quot;过滤器就是奖励&quot;">​</a></h3><p>数学可用最终答案核对；代码可用测试；开放对话只能用 RM 或 LLM 裁判。过滤器错，SFT 会强化错法。这与<a href="/llm/instruction-data-lineage">谱系</a>里教师错误同源，只是教师换成了「当前模型 + 过滤器」。</p><p><span class="marginnote">Yuan 等人文标题为 Scaling Relationship on Learning Mathematical Reasoning with Large Language Models：RFT 用模型自己的正确样本扩充 SFT。RAFT 把「正确」推广为奖励排序后取 top。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>固定提示集 \\(\\mathcal{X}\\)（可含难例）。对每个 \\(x\\)，从当前 \\(\\theta\\) 采 \\(N\\) 个完成，温度略高于部署以增加多样性。过滤器留下 \\(k\\) 个（或通过/失败二值）。用通过的 \\((x,y)\\) 组成新训练集，<a href="/llm/chat-template">chat template</a> 与掩码与普通 SFT 相同，<a href="/llm/lora-vs-full-lr">学习率</a>按参数化选，epoch 少，避免背这一轮的幸运样本。更新 \\(\\theta\\)，进入下一轮；提示集可逐渐加难。</p><p>负例：仅做正例 SFT 是标准 RFT。若把失败完成当「不要这样写」，需要对比损失或 DPO，那就离开纯拒绝采样、进入偏好。本课默认正例循环。</p>',13)),(l(),n(B,null,{default:e(()=>[r(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20Pi%5B%22%E5%BD%93%E5%89%8D%E7%AD%96%E7%95%A5%22%5D%20--%3E%20Sam%5B%22%E5%AF%B9%E6%8F%90%E7%A4%BA%E9%87%87%20N%20%E4%B8%AA%E5%AE%8C%E6%88%90%22%5D%0A%20%20Sam%20--%3E%20F%5B%22%E9%AA%8C%E8%AF%81%E5%99%A8%E6%88%96%20RM%20%E8%BF%87%E6%BB%A4%22%5D%0A%20%20F%20--%3E%20SFT%5B%22%E4%BB%85%E5%9B%9E%E5%A4%8D%20SFT%22%5D%0A%20%20SFT%20--%3E%20Pi%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"\\(N\\) 与计算预算线性；过大则同一提示下完成高度相关，边际信息下降。去重（n-gram / 嵌入）与多样性温度是实用旋钮。Llama 2 把拒绝采样与 RLHF 并列：前者产示范，后者直接优化偏好，可以接力而不是二选一。",-1)),a[4]||(a[4]=E("p",null,[E("span",{class:"marginnote"},"数字实例：\\(N=16\\)、每条完成约 1000 token，一万条提示一轮就要采约 \\(1.6\\) 亿 token——RFT 的账主要记在推理吞吐上而不是训练卡上。\\(N\\) 翻倍成本翻倍，但同一提示的完成高度相关，边际信息远低于翻倍；去重与温度就是在这里省钱的。")],-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,"每轮 SFT 把质量堆到过滤器通过的区域内。若过滤器是精确验证器，循环近似在扩大「会做这道题」的测度，类似自举。若过滤器是 RM，循环近似强化 RM 的高水平集，包括 RM 的虚假相关（更长、更客气）。KL 相对第一轮 SFT 基线会悄悄增大，即使没有显式 KL 项——因为每轮都在自己的高分尾巴上再训。",-1)),(l(),n(B,null,{default:e(()=>[r(o,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOOP%5B%22%E6%AF%8F%E8%BD%AE%EF%BC%9A%E9%87%87%20N%20%E2%86%92%20%E8%BF%87%E6%BB%A4%20%E2%86%92%20SFT%20%E8%87%AA%E8%BA%AB%E9%AB%98%E5%88%86%E5%B0%BE%E5%B7%B4%22%5D%20--%3E%20F%7B%22%E8%BF%87%E6%BB%A4%E5%99%A8%E6%98%AF%E4%BB%80%E4%B9%88%EF%BC%9F%22%7D%0A%20%20F%20--%3E%7C%22%E7%B2%BE%E7%A1%AE%E9%AA%8C%E8%AF%81%E5%99%A8%EF%BC%9A%E6%A0%87%E5%87%86%E7%AD%94%E6%A1%88%20%2F%20%E6%B5%8B%E8%AF%95%22%7C%20V%5B%22%E6%89%A9%E5%A4%A7%E7%9C%9F%E4%BC%9A%E5%81%9A%E7%9A%84%E6%B5%8B%E5%BA%A6%EF%BC%9A%E8%87%AA%E4%B8%BE%E5%B9%B2%E5%87%80%22%5D%0A%20%20F%20--%3E%7C%22RM%EF%BC%9A%E5%AD%A6%E5%87%BA%E6%9D%A5%E7%9A%84%E4%BB%A3%E7%90%86%22%7C%20R%5B%22%E5%BC%BA%E5%8C%96%20RM%20%E9%AB%98%E6%B0%B4%E5%B9%B3%E9%9B%86%EF%BC%9A%E5%90%AB%E8%99%9A%E5%81%87%E7%9B%B8%E5%85%B3%22%5D%0A%20%20R%20--%3E%20H%5B%22%E5%A4%9A%E8%BD%AE%E5%90%8E%E5%88%B7%20RM%20%E7%99%96%E5%A5%BD%EF%BC%9A%E6%9B%B4%E9%95%BF%E6%9B%B4%E5%AE%A2%E6%B0%94%22%5D%0A%20%20LOOP%20--%3E%20K%5B%22%E6%B2%A1%E6%9C%89%E6%98%BE%E5%BC%8F%20KL%20%E9%A1%B9%EF%BC%8CKL%20%E4%BB%8D%E9%80%90%E8%BD%AE%E5%A2%9E%E5%A4%A7%22%5D%0A%20%20K%20--%3E%20EARLY%5B%22%E8%BD%AE%E6%95%B0%E5%B0%B1%E6%98%AF%E9%A2%84%E7%AE%97%EF%BC%9A%E6%97%A9%E5%81%9C%E6%88%96%E6%8D%A2%E8%BF%87%E6%BB%A4%E5%99%A8%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=A('<p><span class="marginnote">常见误区：初学者容易以为「失败样本被扔掉」等于「模型学到了不要这样写」。纯正例循环里，负例只是没被强化，并没有被显式压低；想真正压低失败写法要上对比损失或 DPO，那就离开了本课的纯拒绝采样。</span></p><p>与纯 SFT 比：数据随策略进化，覆盖学生真实会犯的错附近的正确修补。与 PPO 比：没有逐步信用分配，整个 \\(y\\) 被接受或拒绝，长链中间错误只能靠「整段被拒」间接压。这是样本效率换优化复杂度。</p><p><span class="marginnote"><a href="/llm/lora">LoRA</a> 上做 RFT：每轮适配器迅速拟合本轮 top 完成，下一轮采样多样性下降，循环早停。全参或较高秩更利于多轮自举。NEFTune 可减轻背诵本轮样本。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>无可靠过滤器时不要做 RFT，回去精选 SFT。过滤器比学生强很多时（编译器、标准答案），RFT 极划算；过滤器与学生同弱时，循环放大共同偏见。安全领域用 RM 做拒绝采样，可能系统性地留下「看起来安全」的完成。计算上，RFT 的主成本在采样，不在 SFT 步，账应记在推理吞吐。</p><p>本单元收束：数据谱系、仅回复、打包、NEFTune、学习率分叉、长上下文、领域两阶段、SFT/RL 分界、RFT 循环。后课默认这些工程契约已成立，转向低秩之外的 PEFT。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RFT/RAFT：当前策略采样 → 过滤 → 当示范 SFT，再循环。</li><li>训练–解码对齐优于静态离线示范；代价是过滤器质量与采样算力。</li><li>精确验证器上自举干净；RM 过滤会强化奖励癖好。</li><li>正例 SFT 不自动提供负例；要排序就换偏好损失。</li><li>LoRA 上多轮 RFT 容易多样性塌缩，需早停或提高容量。</li><li>出处：Yuan 等，数学 RFT，2023；Dong 等，RAFT，TMLR 2023；Touvron 等，Llama 2，2023。</li></ul>',8))])}const S=i(p,[["render",T]]);export{D as __pageData,S as default};
